let activeGroup='all';
let currentResults=[...GEO_SPECIES];
let selected=null;
const imageMemory=new Map();
const imagePending=new Set();
const imageQueue=[];
let imageObserver=null;
const $=id=>document.getElementById(id);

function normalize(value){
  return String(value||'').toLocaleLowerCase('ka-GE').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}

function tokenize(value){
  return normalize(value).split(/[^\p{L}\p{N}]+/u).filter(Boolean);
}

function matches(item,q){
  if(!q)return true;
  const needle=normalize(q);
  const hay=normalize([
    item.ka,item.en,item.latin,item.group,item.habitat,item.regions,item.season,item.active,item.desc,
    ...(item.tags||[])
  ].join(' '));
  if(hay.includes(needle)) return true;
  const tokens=tokenize(needle);
  return tokens.length>0 && tokens.every(token=>hay.includes(token));
}

function groupIcon(group){
  if(group==='ფრინველი') return '🐦';
  if(group==='ძუძუმწოვარი') return '🦌';
  return '🐟';
}

function imageSearchUrl(item){
  const query=encodeURIComponent(item.latin || item.en || item.ka);
  return `https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${query}&gsrnamespace=6&gsrlimit=1&prop=imageinfo&iiprop=url&iiurlwidth=720&format=json&origin=*`;
}

async function fetchSpeciesImage(item){
  if(imageMemory.has(item.id)) return imageMemory.get(item.id);
  if(imagePending.has(item.id)) return null;
  imagePending.add(item.id);
  try{
    const response=await fetch(imageSearchUrl(item),{mode:'cors'});
    if(!response.ok) throw new Error('image api');
    const data=await response.json();
    const pages=data.query && data.query.pages ? Object.values(data.query.pages) : [];
    const info=pages[0] && pages[0].imageinfo && pages[0].imageinfo[0];
    const image=info && (info.thumburl || info.url);
    const result=image ? {src:image,credit:'Wikimedia Commons'} : null;
    imageMemory.set(item.id,result);
    return result;
  }catch(error){
    imageMemory.set(item.id,null);
    return null;
  }finally{
    imagePending.delete(item.id);
  }
}

function attachImage(card,item){
  const img=card.querySelector('.u-photo');
  if(!img || img.dataset.loaded==='1') return;
  img.dataset.loaded='1';
  fetchSpeciesImage(item).then(result=>{
    if(result && result.src){
      img.src=result.src;
      img.classList.add('loaded');
      img.closest('.u-image')?.classList.add('has-image');
      img.closest('.u-image')?.setAttribute('data-credit',result.credit||'');
    }else{
      img.closest('.u-image')?.classList.add('image-fallback');
    }
  });
}

function ensureImageObserver(){
  if(imageObserver || !('IntersectionObserver' in window)) return;
  imageObserver=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        const card=entry.target;
        const id=Number(card.dataset.id);
        const item=GEO_SPECIES.find(x=>x.id===id);
        if(item) attachImage(card,item);
        imageObserver.unobserve(card);
      }
    });
  },{rootMargin:'220px'});
}

function observeCards(){
  ensureImageObserver();
  document.querySelectorAll('.u-card').forEach(card=>{
    if(imageObserver) imageObserver.observe(card);
    else attachImage(card,GEO_SPECIES.find(x=>x.id===Number(card.dataset.id)));
  });
}

function fallbackImageMarkup(item){
  return `<div class="u-image"><div class="image-loader">${item.icon}</div><img class="u-photo" loading="lazy" alt="${item.ka}" src="" data-loaded="0"></div>`;
}

function renderCounts(){
  $('countAll').textContent=`(${GEO_SPECIES.length})`;
  $('countBird').textContent=`(${GEO_SPECIES.filter(x=>x.group==='ფრინველი').length})`;
  $('countMammal').textContent=`(${GEO_SPECIES.filter(x=>x.group==='ძუძუმწოვარი').length})`;
  $('countFish').textContent=`(${GEO_SPECIES.filter(x=>x.group==='თევზი').length})`;
}

function renderQuick(){
  const picks=['მწყერი','ხოხობი','კაკაბი','მურა დათვი','მგელი','მდინარის კალმახი','კობრი','ლოქო'];
  $('quickPills').innerHTML=picks.map(x=>`<button type="button">${x}</button>`).join('');
  $('quickPills').querySelectorAll('button').forEach(button=>{
    button.onclick=()=>{
      $('universalSearch').value=button.textContent;
      activeGroup='all';
      syncFilters();
      renderResults();
    };
  });
}

function renderSuggestions(query){
  const box=$('liveSuggestions');
  if(!query){box.innerHTML='';return;}
  const items=GEO_SPECIES.filter(item=>matches(item,query)).slice(0,9);
  box.innerHTML=items.map(item=>`<button type="button" data-id="${item.id}">${groupIcon(item.group)}<b>${item.ka}</b><small>${item.group} · ${item.en}</small></button>`).join('');
  box.querySelectorAll('button').forEach(button=>button.onclick=()=>{
    openDetail(Number(button.dataset.id));
    box.innerHTML='';
  });
}

function renderResults(){
  const query=$('universalSearch').value.trim();
  currentResults=GEO_SPECIES.filter(item=>(activeGroup==='all'||item.group===activeGroup)&&matches(item,query));
  $('resultCount').textContent=`${currentResults.length} შედეგი`;
  $('resultHint').textContent=query?`ძიება: „${query}“`:'აირჩიე სახეობა ან ჩაწერე საძიებო სიტყვა';
  $('resultGrid').innerHTML=currentResults.map(item=>`
    <article class="u-card" data-id="${item.id}" tabindex="0" role="button" aria-label="${item.ka}-ს ინფორმაციის გახსნა">
      ${fallbackImageMarkup(item)}
      <div class="u-top"><span class="u-tag">${item.group}</span><span>${item.latin}</span></div>
      <h3>${item.ka}</h3>
      <p>${item.en}</p>
      <div class="u-meta"><span>📍 ${item.regions.split(',')[0]}</span><span>🕒 ${item.active.split(' ')[0]}</span></div>
    </article>`).join('') || `
    <div class="empty-results"><div>🔍</div><h3>ვერ მოიძებნა</h3><p>სცადე სხვა სიტყვა, ლათინური სახელი ან კატეგორია.</p></div>`;

  $('resultGrid').querySelectorAll('.u-card').forEach(card=>{
    const handler=()=>openDetail(Number(card.dataset.id));
    card.addEventListener('click',handler);
    card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();handler();}});
  });
  renderSuggestions(query);
  observeCards();
}

function openDetail(id){
  selected=GEO_SPECIES.find(item=>item.id===id);
  if(!selected)return;
  activeGroup=selected.group;
  syncFilters();
  $('detailPanel').innerHTML=`
    <div class="detail-photo-wrap" data-detail-id="${selected.id}">
      <div class="detail-image-fallback">${selected.icon}</div>
      <img id="detailSpeciesImage" alt="${selected.ka}" loading="eager" src="">
      <button class="image-open-button" type="button" id="openSpeciesImage">🔍 დიდი სურათი</button>
    </div>
    <div class="detail-hero"><div class="detail-icon">${selected.icon}</div><div><span class="u-tag">${selected.group}</span><h2>${selected.ka}</h2><p>${selected.en} • <i>${selected.latin}</i></p></div></div>
    <div class="detail-section"><h4>ზოგადი აღწერა</h4><p>${selected.desc}</p></div>
    <div class="detail-info-grid">
      <div><span>🌍 ჰაბიტატი</span><b>${selected.habitat}</b></div>
      <div><span>📍 გავრცელება</span><b>${selected.regions}</b></div>
      <div><span>📅 სეზონი</span><b>${selected.season}</b></div>
      <div><span>🕒 აქტივობა</span><b>${selected.active}</b></div>
    </div>
    <div class="detail-section"><h4>სურათის წყარო</h4><p class="image-source-note">სურათი იტვირთება Wikimedia Commons-იდან, როცა ინტერნეტი ხელმისაწვდომია. თუ ონლაინ სურათი ვერ ჩაიტვირთა, რჩება სახეობის იდენტიფიკაციის ვიზუალური placeholder.</p></div>
    <div class="detail-section"><h4>რუკა</h4><p>რუკაზე მითითებული გავრცელება არის რეგიონული საინფორმაციო დონე და არ ნიშნავს კონკრეტულ ბუდეს, სოროს, თევზის ზუსტ ადგილს ან სხვა მგრძნობიარე წერტილს.</p><a class="btn primary" href="map.html?species=${encodeURIComponent(selected.ka)}">🗺️ რუკის გახსნა</a></div>
    <div class="detail-tags">${(selected.tags||[]).map(tag=>`<span>${tag}</span>`).join('')}</div>`;

  const detailImage=$('detailSpeciesImage');
  fetchSpeciesImage(selected).then(result=>{
    if(result && result.src){
      detailImage.src=result.src;
      detailImage.classList.add('loaded');
      detailImage.previousElementSibling?.classList.add('hidden');
      $('openSpeciesImage').disabled=false;
      $('openSpeciesImage').onclick=()=>openImageModal(result.src,selected.ka,result.credit);
    }else{
      $('openSpeciesImage').disabled=true;
      $('openSpeciesImage').title='სურათი ვერ ჩაიტვირთა';
    }
  });
  $('detailPanel').scrollIntoView({behavior:'smooth',block:'start'});
}

function openImageModal(src,title,credit){
  if(!src || !$('imageModal'))return;
  $('modalImage').src=src;
  $('modalImage').alt=title||'';
  $('modalTitle').textContent=title||'';
  $('modalCredit').textContent=credit||'';
  $('imageModal').classList.add('open');
  $('imageModal').setAttribute('aria-hidden','false');
}

function closeImageModal(){
  if(!$('imageModal'))return;
  $('imageModal').classList.remove('open');
  $('imageModal').setAttribute('aria-hidden','true');
  $('modalImage').src='';
}

function syncFilters(){
  document.querySelector('.filter.active')?.classList.remove('active');
  const active=document.querySelector(`.filter[data-group="${activeGroup}"]`);
  if(active)active.classList.add('active');
}

function initSearch(){
  renderCounts();
  renderQuick();
  renderResults();
  syncFilters();
  const input=$('universalSearch');
  input.addEventListener('input',()=>renderResults());
  input.addEventListener('focus',()=>renderSuggestions(input.value.trim()));
  $('clearSearch').onclick=()=>{input.value='';renderResults();input.focus();};
  document.querySelectorAll('.filter').forEach(button=>button.onclick=()=>{activeGroup=button.dataset.group;syncFilters();renderResults();});
  input.addEventListener('keydown',event=>{
    if(event.key==='Enter' && currentResults[0])openDetail(currentResults[0].id);
    if(event.key==='Escape'){$('liveSuggestions').innerHTML='';}
  });
  document.addEventListener('click',event=>{
    if(!event.target.closest('.universal-search-wrap'))$('liveSuggestions').innerHTML='';
    if(event.target.matches('[data-close-modal]'))closeImageModal();
  });
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeImageModal();});
}

document.addEventListener('DOMContentLoaded',()=>{if($('universalSearch'))initSearch();});

